import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import API from "../services/api";
import Zoom from "react-medium-image-zoom";
import "react-medium-image-zoom/dist/styles.css";
import "./ProductoDetalle.css";

function ProductoDetalle(){

 const { id } = useParams();
 const navigate = useNavigate();

 const [producto,setProducto] = useState(null);

 const usuario = JSON.parse(localStorage.getItem("usuario"));


 useEffect(()=>{

  cargarProducto();

 },[]);


 const cargarProducto = async ()=>{

  try{

   const res = await API.get(`/productos/${id}`);

   setProducto(res.data);

  }catch(error){

   console.log("Error cargando producto",error);

  }

 };


 // ⭐ FAVORITO

 const agregarFavorito = async ()=>{

  try{

   const res = await API.post("/favoritos",{
    id_usuario:usuario.id_usuario,
    id_producto:producto.id_producto
   });

   alert(res.data.mensaje);

  }catch(error){

   console.log(error);
   alert("Error agregando favorito");

  }

 };


 // 🛒 COMPRAR PRODUCTO

 const comprarProducto = async ()=>{

  try{

   const res = await API.post("/comprar",{
    id_producto:producto.id_producto
   });

   alert(res.data.mensaje);

   cargarProducto(); // refresca estado

  }catch(error){

   console.log(error);
   alert("Error en la compra");

  }

 };


 // 💬 CONTACTAR VENDEDOR

 const contactarVendedor = ()=>{

  navigate(`/chat/${producto.id_vendedor}`);

 };


 if(!producto){

  return <h2 style={{textAlign:"center"}}>Cargando producto...</h2>;

 }



return (
  <div className="detalle-wrapper">
    <div className="detalle-container">
      <header className="detalle-header">
        <button className="btn-back" onClick={() => navigate(-1)}>
          <i className="feather-arrow-left"></i> Volver al catálogo
        </button>
      </header>

      <div className="detalle-grid">
        {/* COLUMNA IZQUIERDA: GALERÍA */}
        <div className="detalle-visuals">
          <div className="main-image-card">
            <Zoom>
              <img
                src={`http://localhost:3000/uploads/${producto.imagen}`}
                alt={producto.tipo_producto}
                className="img-principal"
              />
            </Zoom>
          </div>
          
          <div className="certificado-section">
            <h4><Feather.FileText size={16} /> Certificado de Autenticidad</h4>
            <div className="certificado-preview">
              <Zoom>
                <img
                  src={`http://localhost:3000/uploads/${producto.certificado}`}
                  alt="Certificado GIA/CDTEC"
                />
              </Zoom>
            </div>
          </div>
        </div>

        {/* COLUMNA DERECHA: INFORMACIÓN */}
        <div className="detalle-content">
          <div className="content-header">
            <span className="sku-tag">ID: #00{producto.id_producto}</span>
            <h1 className="producto-titulo">{producto.tipo_producto} Premium</h1>
            <p className="vendedor-link">Por: <span>{producto.vendedor}</span></p>
          </div>

          <div className="precio-hero">
            <label>Precio de Inversión</label>
            <h1>${Number(producto.valor).toLocaleString()} <small>USD</small></h1>
            {producto.estado === "vendido" && <span className="sold-out-badge">Pieza Vendida</span>}
          </div>

          <div className="specs-container">
            <h3>Especificaciones Técnicas</h3>
            <div className="specs-grid">
              <div className="spec-tile">
                <label>Color</label>
                <p>{producto.color}</p>
              </div>
              <div className="spec-tile">
                <label>Peso</label>
                <p>{producto.peso} Carats</p>
              </div>
              <div className="spec-tile">
                <label>Tratamiento</label>
                <p>{producto.tratamiento}</p>
              </div>
              <div className="spec-tile">
                <label>Estado</label>
                <p className="capitalize">{producto.estado}</p>
              </div>
            </div>
          </div>

          {producto.tipo_producto === "joya" && (
            <div className="joya-details-card">
              <h3>Composición de la Joya</h3>
              <ul>
                <li><span>Oro:</span> {producto.oro}</li>
                <li><span>Plata:</span> {producto.plata}</li>
                <li><span>Oro Rosado:</span> {producto.oro_rosado}</li>
              </ul>
            </div>
          )}

          <div className="acciones-premium">
            <button 
              className="btn-buy" 
              onClick={comprarProducto}
              disabled={producto.estado === "vendido"}
            >
              {producto.estado === "vendido" ? "NO DISPONIBLE" : "ADQUIRIR PIEZA"}
            </button>
            
            <div className="secondary-btns">
              <button className="btn-fav-gold" onClick={agregarFavorito}>
                <Feather.Heart size={18} /> Guardar
              </button>
              <button className="btn-chat-blue" onClick={contactarVendedor}>
                <Feather.MessageCircle size={18} /> Consultar
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
);
}
